  loader.value = {
    status: false,
    msgId: null,
  };
  failToSend.value = null;
  message.value = null;
  leaveChat()
  emits("closeChat");
};



onMounted(() => {

  channel.value = supabase.channel(chat.value?.session).on('postgres_changes', { event: "*", schema: "public", table: "chatRooms" }, (payload) => {
    initSocket(payload.new)

  }).subscribe()

  handleScroll()
})



watch(isTyping, (val) => {
